import json
from dataclasses import dataclass, field
from typing import List, Optional, Dict, Any


@dataclass
class LineItem:
    description: str
    amount: float
    quantity: Optional[float] = None
    unit_price: Optional[float] = None


@dataclass
class ExpenseRecord:
    transaction_id: str
    document_type: str  # "invoice" or "receipt"
    vendor_name: str
    transaction_date: str
    total_amount: float
    currency: str = "USD"
    tax_amount: Optional[float] = None
    line_items: List[LineItem] = field(default_factory=list)
    raw_extraction_data: Dict[str, Any] = field(default_factory=dict)
    notes: Optional[str] = None

    def to_json(self):
        return json.dumps(self, default=lambda o: o.__dict__, indent=2)

    @classmethod
    def from_json(cls, json_string):
        data = json.loads(json_string)
        line_items = [LineItem(**item) for item in data.pop("line_items", [])]
        return cls(line_items=line_items, **data)

from google.cloud import translate_v2 as translate

def translate_invoice_notes(text_content, target_language='en', config=None):
    config = config or {}
    translate_client = translate.Client()

    # The Google Cloud Translation API client automatically handles project ID and authentication
    # using credentials configured in the environment (e.g., GOOGLE_APPLICATION_CREDENTIALS)

    result = translate_client.translate(
        text_content,
        target_language=target_language
    )

    return {
        "original_text": text_content,
        "translated_text": result['translatedText'],
        "source_language": result['detectedSourceLanguage']
    }

from google.cloud import firestore

def persist_expense_record(expense_record, config=None):
    config = config or {}
    # Initialize Firestore DB client
    db = firestore.Client(project=config["project_id"])

    collection_ref = db.collection(config["collection_name"])

    # Add a new document with a generated ID
    # The to_dict() method of ExpenseRecord would convert it to a dictionary
    # For this example, we'll assume expense_record is already a dict or has a to_dict method
    if hasattr(expense_record, 'to_json'):
        doc_ref = collection_ref.add(expense_record.to_json())
    else:
        doc_ref = collection_ref.add(expense_record)

    return {"status": "success", "document_id": doc_ref[1].id}
